import pandas as pd

# Convert 'stages' to numeric values
df['stages'] = df['stages'].str.replace(' stages', '').str.replace(' stage', '').astype(int)

# Convert 'acts' to numeric values where possible
def parse_acts(acts_str):
    if '+' in acts_str:
        return int(acts_str.split('+')[0].strip())
    else:
        return int(acts_str.split()[0].strip())

df['acts'] = df['acts'].apply(parse_acts)

# Calculate mean and standard deviation for stages and acts
mean_stages = df['stages'].mean()
std_stages = df['stages'].std()

mean_acts = df['acts'].mean()
std_acts = df['acts'].std()

# Identify outliers (more than 2 standard deviations from the mean)
outlier_stages = df[(df['stages'] < (mean_stages - 2 * std_stages)) | (df['stages'] > (mean_stages + 2 * std_stages))]
outlier_acts = df[(df['acts'] < (mean_acts - 2 * std_acts)) | (df['acts'] > (mean_acts + 2 * std_acts))]

# Check if any outlier exists
if not outlier_stages.empty or not outlier_acts.empty:
    final_answer_value = 'Yes'
else:
    final_answer_value = 'No'

